export type Backend = {
  name: string;
  url: string;
  status: string;
  models: string[];
};

export type BenchmarkInfo = {
  name: string;
  category: string;
  description: string;
  scoring_mode: string;
  estimated_runtime_minutes: number;
  dataset_size: number;
  stability: string;
  quant_sensitive: boolean;
  required_capabilities: string[];
};

export type Session = {
  id: number;
  model_config_id: number;
  preset_used: string | null;
  status: string;
  started_at: string;
  completed_at: string | null;
};

export type Run = {
  id: number;
  eval_session_id: number;
  benchmark_name: string;
  benchmark_version: string;
  status: string;
  score: number | null;
  score_breakdown: string | null;
  runtime_seconds: number | null;
  subset_mode: string | null;
  scoring_mode: string | null;
  error_info: string | null;
  started_at: string | null;
  completed_at: string | null;
};

export type RunDetail = {
  id: number;
  run_id: number;
  question_index: number;
  prompt: string;
  raw_output: string;
  parsed_output: string;
  correct_answer: string;
  is_correct: boolean;
  latency_ms: number | null;
  token_count: number | null;
};

export type SessionDetails = {
  session: Session;
  runs: Run[];
};

export type StartSessionConfig = {
  model_name: string;
  backend_type: string;
  backend_url: string;
  prompt_format?: string;
  context_length?: number;
  sampling_params?: Record<string, unknown>;
  benchmarks: Record<string, string>;
  preset?: string;
};

const BASE = "";

async function request<T>(path: string, options?: RequestInit): Promise<T> {
  const res = await fetch(`${BASE}${path}`, options);
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`HTTP ${res.status}: ${text}`);
  }
  return res.json() as Promise<T>;
}

export function fetchHealth(): Promise<{ status: string }> {
  return request("/api/health");
}

export function fetchBackends(): Promise<Backend[]> {
  return request("/api/models/backends");
}

export function fetchBenchmarks(): Promise<BenchmarkInfo[]> {
  return request("/api/benchmarks");
}

export function fetchPresets(): Promise<Record<string, unknown>> {
  return request("/api/benchmarks/presets");
}

export function fetchSessions(signal?: AbortSignal): Promise<Session[]> {
  return request("/api/sessions", { signal });
}

export function fetchSession(id: number, signal?: AbortSignal): Promise<SessionDetails> {
  return request(`/api/sessions/${id}`, { signal });
}

export function startSession(config: StartSessionConfig): Promise<{ session_id: number }> {
  return request("/api/sessions/start", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(config),
  });
}

export function fetchRunDetails(runId: number): Promise<RunDetail[]> {
  return request(`/api/runs/${runId}/details`);
}

export function cancelSession(id: number): Promise<{ status: string }> {
  return request(`/api/sessions/${id}/cancel`, { method: "POST" });
}

import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { fetchSessions } from "../api/client";
import type { Session } from "../api/client";

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    completed: "bg-green-900 text-green-300",
    running: "bg-blue-900 text-blue-300",
    partial: "bg-yellow-900 text-yellow-300",
    failed: "bg-red-900 text-red-300",
    pending: "bg-gray-800 text-gray-400",
  };
  return (
    <span
      className={`px-2 py-0.5 rounded text-xs font-medium ${
        colors[status] ?? "bg-gray-800 text-gray-400"
      }`}
    >
      {status}
    </span>
  );
}

export default function History() {
  const [sessions, setSessions] = useState<Session[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [reloadAttempt, setReloadAttempt] = useState(0);

  useEffect(() => {
    const controller = new AbortController();
    setLoading(true);
    setError(null);

    fetchSessions(controller.signal)
      .then(setSessions)
      .catch((cause: unknown) => {
        if (cause instanceof Error && cause.name === "AbortError") return;
        setError(cause instanceof Error ? cause.message : "Failed to load evaluation history");
      })
      .finally(() => {
        if (!controller.signal.aborted) setLoading(false);
      });

    return () => controller.abort();
  }, [reloadAttempt]);

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-white">Evaluation History</h1>
        <p className="text-gray-400 text-sm mt-1">All past benchmark sessions</p>
      </div>

      {loading ? (
        <p className="text-gray-500 text-sm">Loading...</p>
      ) : error ? (
        <div
          role="alert"
          className="flex flex-col items-start gap-3 rounded-lg border border-red-800 bg-red-950 px-4 py-3 text-sm text-red-300 sm:flex-row sm:items-center sm:justify-between"
        >
          <span>Could not load evaluation history: {error}</span>
          <button
            type="button"
            onClick={() => setReloadAttempt((attempt) => attempt + 1)}
            className="rounded-md bg-red-900 px-3 py-1.5 font-medium text-red-100 hover:bg-red-800"
          >
            Retry
          </button>
        </div>
      ) : sessions.length === 0 ? (
        <div className="border border-gray-800 rounded-lg p-6 text-center">
          <p className="text-gray-500">No evaluations yet</p>
          <Link
            to="/new"
            className="inline-block mt-3 px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg text-sm font-medium transition-colors"
          >
            Run your first evaluation
          </Link>
        </div>
      ) : (
        <div className="space-y-2">
          {sessions.map((s) => (
            <Link
              key={s.id}
              to={`/results/${s.id}`}
              className="flex items-center justify-between bg-gray-900 border border-gray-800 rounded-lg px-4 py-3 hover:border-gray-700 hover:bg-gray-800 transition-colors"
            >
              <div className="flex items-center gap-4">
                <span className="text-gray-600 text-sm font-mono">#{s.id}</span>
                <div>
                  <span className="text-sm font-medium text-white">Session #{s.id}</span>
                  {s.preset_used && (
                    <span className="ml-2 text-xs text-gray-500">
                      preset: {s.preset_used}
                    </span>
                  )}
                  <p className="text-xs text-gray-500 mt-0.5">
                    {new Date(s.started_at).toLocaleString()}
                  </p>
                </div>
              </div>
              <StatusBadge status={s.status} />
            </Link>
          ))}
        </div>
      )}
    </div>
  );
}
